    'RegistrationText'=>'Зарегистрированным экземплярам SimpleRisk сразу предоставляется доступ к Extras «Upgrade» и «Secure Controls Framework (SCF)».  Extra «Upgrade» даёт возможность создавать резервную копию и выполнять обновление вашего экземпляра SimpleRisk одним нажатием кнопки.  Extra «Secure Controls Framework (SCF)» предоставляет единый фреймворк контролей, интегрированный в функциональность управления (Governance) SimpleRisk.  При регистрации SimpleRisk ваша регистрационная информация будет отправлена на сервер, размещённый SimpleRisk.  Предоставленная регистрационная информация будет использоваться SimpleRisk для уведомления клиентов о новых версиях и обновлениях безопасности.  Регистрация SimpleRisk означает вашу подписку на наши маркетинговые рассылки, но вы можете отказаться от них в любое время, воспользовавшись ссылкой для отказа от подписки в этих рассылках.  SimpleRisk уважает конфиденциальность наших клиентов, и информация, предоставленная нам в процессе регистрации SimpleRisk, никогда не будет продана третьим лицам.',
