    'SettingsDesc'                        => 'Настройте общесистемные параметры: базовый URL-адрес, безопасность, язык по умолчанию, часовой пояс, параметры оценки рисков по умолчанию и многое другое.',
    'SettingsPreferencesDesc'             => 'Значения по умолчанию и поведенческие настройки в SimpleRisk: язык, часовой пояс, статусы аудита, требования к сопоставлению рисков, переключатели поведения пользовательского интерфейса и тому подобное.',
