    'SettingsLoggingDesc'                 => 'Настройка отладочного и аудиторского журналирования: уровни ведения журналов, срок хранения и расположение файлов журналов.',
    'HealthCheckDesc'                     => 'Диагностика состояния системы: версия PHP, расширения, права доступа к файлам, подключение к базе данных, расписание cron и активации Extra.',
    'AnnouncementsDesc'                   => 'Создание баннерных объявлений, видимых всем пользователям, и управление ими.',
