    'RiskConfigurationDesc'               => 'Настройка правил оценки рисков: уровни, риск-аппетит, пороговые значения SLA и классические формулы риска / формулы с учетом факторов влияния.',
    'RiskAndThreatCatalogDesc'            => 'Ведение каталога значений рисков и угроз, используемых в выпадающих списках.',
    'AddAndRemoveValuesDesc'              => 'Управление значениями выпадающих списков для полей риска: местоположение, источник, категория, команда, технология и другие.',
