    'UserManagementDesc'                  => 'Добавление, редактирование, отключение и сброс учетных записей пользователей; управление политикой паролей.',
    'RoleManagementDesc'                  => 'Определите роли и права доступа, предоставляемые каждой ролью.',
    'TeamManagementDesc'                  => 'Создание команд и управление ими; команды используются для фильтрации видимости записей.',
    'SeparationExtraDesc'                 => 'Функция «Разделение по командам» ограничивает просмотр рисков только пользователями, входящими в команду, к которой этот риск назначен. В базовом продукте SimpleRisk без этой функции каждый пользователь может видеть все риски.',
    'CustomAuthenticationExtraDesc'       => 'Extra «Пользовательская аутентификация» обеспечивает поддержку аутентификации Active Directory и SAML. В продукте SimpleRisk Core без этого Extra единственный вариант — создавать новых пользователей в репозитории идентификационных данных SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Дополнительная функция «Зашифрованная база данных» генерирует случайный 256-битный ключ шифрования AES, а затем использует его для шифрования конфиденциального текста перед его добавлением в базу данных SimpleRisk. Это предотвращает просмотр или изменение данных кем-либо без непосредственного использования приложения SimpleRisk.',
    'OrganizationManagementDesc'          => 'Extra «Организационная иерархия» дает возможность определять несколько бизнес-подразделений, каждое из которых может включать любое количество команд. Затем пользователей можно назначать в одну или несколько команд различных бизнес-подразделений. Это влияет на возможность пользователя видеть и использовать команды, пользователей и активы, с которыми он не связан.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Массовое удаление рисков. Используйте с осторожностью — удаление будет безвозвратным.',
    'AuditTrailDesc'                      => 'Поиск и экспорт системного журнала аудита действий пользователей.',
    'ImportExportExtraDesc'               => 'Extra «Импорт-экспорт» позволяет импортировать данные в SimpleRisk путем сопоставления полей файла CSV с полями базы данных SimpleRisk. Его можно использовать для импорта результатов аудита из сторонней электронной таблицы, результатов сканирования уязвимостей из другого инструмента, активов из вашей CMDB и многого другого. Также Extra позволяет экспортировать из SimpleRisk файлы CSV с рисками, мерами по снижению рисков, рассмотрениями или комбинированным отчетом по всем трем.',
    'JiraExtraDesc'                       => 'Дополнительный модуль интеграции с Jira предоставляет пользователям возможность двусторонней интеграции с экземпляром Jira. Он позволяет связывать риски с задачами Jira, а также синхронизировать их данные, статус и комментарии.',
    'APIExtraDesc'                        => 'API Extra позволяет клиентам использовать RESTful API для создания скриптовых взаимодействий с другими приложениями, что обеспечивает расширенную автоматизацию и позволяет эффективно использовать существующую инфраструктуру.',
    'AdvancedSearchExtraDesc'             => "Расширенный поиск (Advanced Search Extra) превращает поле поиска в верхней панели в единый поиск по рискам, структурам, средствам контроля, документам, исключениям, тестам, аудитам, активам и группам активов, с полноценной страницей поиска для просмотра результатов. Он отображает только те записи, к которым у пользователя есть доступ.",
    'AssessmentsExtraDesc'                => 'Extra «Оценка рисков» дает пользователям возможность определять контакты, создавать вопросы (включая логику), собирать несколько вопросов в шаблон вопросника, создавать вопросники и отправлять их контактам, просматривать результаты вопросников, добавлять риски на основе этих результатов, сравнивать результаты во времени, импортировать и экспортировать внешние настраиваемые оценки и просматривать журнал аудита оценки рисков.',
    'ActiveAssessmentsDesc'               => 'Просмотр оценок, выполняемых в настоящее время, и управление ими.',
    'WorkflowsExtraDesc'                  => 'Extra «Рабочие процессы» предоставляет визуальный событийно-ориентированный механизм рабочих процессов, который автоматизирует действия по управлению рисками в ответ на события в SimpleRisk. Вы можете создавать рабочие процессы, запускаемые при изменениях — таких как отправка, обновление или рассмотрение риска, — чтобы маршрутизировать утверждения, назначать работу и поддерживать ход процесса без ручного вмешательства.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra — это прямая интеграция между Secure Controls Framework и SimpleRisk. Она импортирует каталог мер контроля SCF и их сопоставления с широким спектром фреймворков соответствия требованиям и кибербезопасности в функциональность управления SimpleRisk, позволяя вам внедрять необходимые фреймворки и управлять их мерами контроля без необходимости создавать их вручную.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Перевод устаревших столбцов типа varchar с датами проверки на столбцы с правильным типом данных даты. Отображается только при необходимости.',
    'DatabaseUpgradeDesc'                 => 'Запуск процедуры обновления базы данных SimpleRisk вручную.',

