    'SpecificUsers' => 'Конкретные пользователи',
    'Help' => 'Помощь',
    'Profile' => 'Профиль',
    'Scoring' => 'Оценка',
    'EncryptionMissingLockTablesPrivilege'   => 'У пользователя базы данных SimpleRisk нет привилегии LOCK TABLES, которая необходима для безопасного шифрования базы данных. Попросите администратора базы данных выполнить инструкцию GRANT, возвращенную в ответе, и попробуйте снова.',
    'EncryptionMissingLockTablesPrivilegeUi' => 'У пользователя базы данных SimpleRisk нет привилегии LOCK TABLES, необходимой для шифрования. Администратору базы данных необходимо выполнить команду: GRANT LOCK TABLES ON {$db}.* TO {$user}; затем повторить попытку.',
    'EncryptionRequiredGrantLabel' => 'Обязательный оператор GRANT:',
    'EncryptionActivationAlreadyRunning' => 'Процесс активации шифрования уже запущен. Дождитесь его завершения или воспользуйтесь функцией восстановления из резервной копии для восстановления данных.',
    'EncryptionActivationEnqueued'           => 'Активация функции Encryption Extra поставлена в очередь. Административный интерфейс будет отслеживать ход выполнения во время шифрования базы данных.',
    'EncryptionActivationEnqueueFailed'      => 'Не удалось поставить в очередь задачу активации шифрования. Подробности см. в журнале отладки.',
    'EncryptionDeactivationEnqueued'         => 'Деактивация функции Encryption Extra поставлена в очередь. Административный интерфейс будет отслеживать ход процесса расшифровки базы данных.',
    'EncryptionDeactivationEnqueueFailed'    => 'Не удалось поставить в очередь задачу деактивации шифрования. Подробности см. в журнале отладки.',
    'EncryptionPipelineInProgress'           => 'Конвейер шифрования (активация, деактивация или восстановление) в настоящее время выполняется. Дождитесь его завершения и попробуйте снова.',
    'EncryptionPipelineInProgressTask'       => 'Конвейер шифрования в настоящее время выполняется (задача №{id}, {type}). Дождитесь его завершения и попробуйте снова.',
    'EncryptionInFlightTitle'            => 'Операция шифрования выполняется',
    'EncryptionInFlightBody'             => 'В данный момент выполняется процесс активации, деактивации или восстановления шифрования. Дождитесь его завершения — после окончания операции страница автоматически обновится — прежде чем повторять попытку.',
    'OK'                                 => 'OK',
    'ActivationGuardFailed'                 => 'Не удалось начать активацию. Подробности см. в предупреждении в заголовке страницы.',
    'EncryptionStageStarting'               => 'Запуск…',
    'EncryptionStageProgress'               => 'Этап {current} из {total}: {name}',
    'EncryptionStageAllDone'                => 'Все этапы завершены.',
    'EncryptionStageEncryptTable'           => 'Шифрование таблицы: {table}',
    'EncryptionStageDecryptTable'           => 'Расшифровка таблицы: {table}',
    'EncryptionActivationInProgress'        => 'Выполняется шифрование базы данных SimpleRisk. Пожалуйста, не закрывайте эту страницу.',
    'EncryptionActivationFailedTitle'       => 'Не удалось активировать шифрование',
    'EncryptionActivationFailedBody'        => 'Не удалось завершить активацию, и база данных может находиться в несогласованном состоянии. Резервная копия, созданная до активации, сохранена — используйте «Восстановить из резервной копии» для восстановления или обратитесь в службу поддержки SimpleRisk.',
    'EncryptionDeactivationInProgress'      => 'Выполняется расшифровка базы данных SimpleRisk. Пожалуйста, не закрывайте эту страницу.',
    'EncryptionDeactivationFailedTitle'     => 'Не удалось деактивировать шифрование',
    'EncryptionDeactivationFailedBody'      => 'Не удалось завершить деактивацию, и база данных может находиться в несогласованном состоянии. Резервная копия зашифрованного состояния сохранена — используйте «Восстановить из резервной копии», чтобы вернуться к зашифрованному состоянию, или обратитесь в службу поддержки SimpleRisk.',
    'RestoreFromBackup'                     => 'Восстановить из резервной копии',
    'RestoreFromBackupNotYetAvailable'      => 'В этой сборке функция восстановления из резервной копии пока недоступна. Для восстановления обратитесь в службу поддержки SimpleRisk.',
    'EncryptionRestoreInProgress'           => 'Выполняется восстановление базы данных SimpleRisk из резервной копии. Это может занять несколько минут.',
    'EncryptionRestoreEnqueueFailed'        => 'Не удалось начать восстановление. Проверьте журналы SimpleRisk и попробуйте снова.',
    'EncryptionStatusActive'                => 'Расширение «Зашифрованная база данных» активно.',
    'EncryptionStatusVersion'               => 'Версия',
    'EncryptionDeactivateCta'               => 'Деактивировать расширение «Зашифрованная база данных»',
    'EncryptionDeactivateCtaHelp'           => 'Расшифровать каждый зашифрованный столбец обратно в открытый текст. В заполненной базе данных это занимает несколько минут.',
    'EncryptionBackupPanelHeading'          => 'Резервная копия до активации',
    'EncryptionBackupCreatedAt'             => 'Создана',
    'EncryptionBackupSize'                  => 'Размер',
    'EncryptionBackupOriginalFilename'      => 'Файл',
    'EncryptionBackupDownloadTooltip'       => 'Нажмите, чтобы скачать копию этого файла резервной копии для автономного хранения.',
    'EncryptionBackupStateRestoring'        => 'В данный момент ведётся восстановление.',
    'EncryptionNoBackupAvailable'           => 'В настоящее время резервная копия, созданная до активации, не хранится. Резервная копия создается в начале каждой активации и перезаписывается при любой последующей активации или деактивации.',
    'EncryptionRestoreCtaHelp'              => 'Выберите этот вариант, если проверка выявила проблемы и вам необходимо вернуться к состоянию, предшествующему шифрованию.',
    'EncryptionRestoreTitle'                => 'Восстановить из резервной копии?',
    'EncryptionRestoreBodyWhy'              => 'Выполняется откат к снимку состояния до шифрования, созданному в начале последней активации. Выберите этот вариант, если при проверке после активации были обнаружены проблемы и необходимо отказаться от шифрования.',
    'EncryptionRestoreBodyWhat'             => 'Каждая запись, добавленная в базу данных после создания резервной копии, будет безвозвратно потеряна, включая риски, меры по снижению рисков, записи журнала аудита и любые другие изменения, сделанные после активации. В рамках восстановления расширение «Зашифрованная база данных» будет деактивировано.',
    'EncryptionDeleteBackupCta'             => 'Удалить резервную копию до шифрования',
    'EncryptionDeleteBackupCtaHelp'         => 'Выберите этот вариант после завершения проверки после шифрования. Именно удаление незашифрованного снимка делает шифрование реально защитным.',
    'EncryptionDeleteBackupTitle'           => 'Удалить резервную копию, созданную до шифрования?',
    'EncryptionDeleteBackupBodyWhy'         => 'Удаление незашифрованного снимка ваших данных, сделанного в начале последней активации. Его хранение в течение неопределённого времени лишает шифрование смысла — любой, кто имеет доступ к базе данных, может прочитать копию до шифрования.',
    'EncryptionDeleteBackupBodyWhat'        => 'Резервная копия в базе данных будет удалена немедленно. Вы больше не сможете использовать «Восстановить из резервной копии» для отката базы данных к состоянию до шифрования. Если позже вы обнаружите проблемы с шифрованием, единственным способом восстановления будет новое восстановление базы данных из ваших рабочих резервных копий.',
    'EncryptionDeleteBackupError'           => 'Не удалось удалить резервную копию. Проверьте журнал отладки и повторите попытку.',
    'EncryptionModalWhyLabel'               => 'Зачем это использовать:',
    'EncryptionModalWhatHappensLabel'       => 'Что произойдет дальше:',
    'EncryptionFieldsPanelHeading'          => 'Зашифрованные поля базы данных',
    'EncryptionFieldsHelp'                  => 'Каждый перечисленный здесь столбец хранится в зашифрованном виде. Во всплывающей подсказке значка замка указан используемый криптографический алгоритм.',
    'EncryptionFieldsTableColumn'           => 'Таблица базы данных',
