    // an operator reads them to unstick an instance that cannot upgrade.
    'UpgradeCorrectionUnknownVersionTitle' => 'Записанная версия базы данных не соответствует реальному релизу',
    'UpgradeCorrectionNoRecordedVersion' => 'В базе данных нет зарегистрированной версии.',
    'UpgradeCorrectionUnknownVersionFinding' => 'База данных сообщает версию \'{$version}\', которая не соответствует ни одному релизу SimpleRisk. Обновление не может выбрать по ней отправную точку.',
    'UpgradeCorrectionUnknownVersionGuidance' => 'Задайте для настройки db_version значение релиза, схему которого фактически имеет эта база данных, а затем запустите обновление еще раз: UPDATE settings SET value=\'<release>\' WHERE name=\'db_version\'. Если значение является заполнителем, например 2026XXXX-001, правильным значением почти всегда является самый последний реальный релиз, установленный до запуска обновления.',
    'UpgradeCorrectionLegacySessionsTitle' => 'Таблица сессий не выдержит преобразования набора символов при обновлении',
    'UpgradeCorrectionLegacySessionsFinding' => '`sessions`.`id` имеет тип VARCHAR({$width}) в таблице MyISAM. Преобразование его в utf8mb4, которое выполняется начиная с версии 20230106-001, превысит лимит индекса MyISAM в 1000 байт и приведет к сбою обновления.',
    'UpgradeCorrectionLegacySessionsGuidance' => 'Одна или несколько активных сессий используют идентификатор длиннее 128 символов. Сокращение столбца сейчас привело бы к выходу этих пользователей из системы, поэтому оно не выполнено. Повторите обновление после истечения срока действия этих сессий.',
