    'EnableCSPHelp' => 'Политика безопасности контента (CSP) разрешает браузеру загружать скрипты, стили, изображения и шрифты только из самого SimpleRisk, а также блокирует встраивание страниц во фреймы и межсайтовую отправку форм. Это самая надежная встроенная защита от межсайтового скриптинга. Оставьте включенной, если она не конфликтует с прокси, расширением браузера или сторонней интеграцией в вашей среде.',
