    'RestoreTemplateConfirmBodyRisk' => 'Это сбросит каждое поле на вкладках «Детали», «Снижение риска» и «Рассмотрение» к значениям по умолчанию для этой группы шаблонов. Другие группы шаблонов не затрагиваются.',
    'RestoreTemplateConfirmBody' => 'Это сбрасывает все поля в этом шаблоне до значений по умолчанию для данной группы шаблонов. Другие группы шаблонов не затрагиваются.',
    // CVSS holder's collapsed Temporal/Environmental/Impact-Modifiers
    // accordion (buildCvssHolder(), risk-details-form.js) -- these three
    // groups are optional CVSS v2 refinements on top of the required Base
    // Score Metrics, so they collapse behind this header by default.
    'AdvancedMetrics' => 'Расширенные метрики',
    // CVSS holder's Base Score Metrics sub-group headers (buildCvssHolder(),
    // risk-details-form.js) -- distinct from the existing 'ExploitabilityMetrics'/
    // 'ImpactMetrics' keys, which the legacy cvss_modal_content.php modal
    // still renders as plain "Exploitability Metrics"/"Impact Metrics" and
    // must keep unchanged. These fold the umbrella "Base Score Metrics"
    // heading into each sub-group's own header instead of a separate label.
    'BaseScoreExploitabilityMetrics' => 'Метрики эксплуатируемости базового показателя',
    'BaseScoreImpactMetrics' => 'Метрики влияния базовой оценки',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'Как можно получить доступ к уязвимости.
• Локальный: требуется локальный доступ, например к консоли или оболочке.
• Смежная сеть: злоумышленник должен находиться в том же физическом или логическом сегменте сети.
• Сеть: уязвимость можно эксплуатировать удаленно через сеть, локальный или смежный доступ не требуется.',
    "AttackComplexityHelp" => "Насколько сложна атака после получения злоумышленником доступа к цели.\n• Высокая: требует особых условий, которые трудно обеспечить.\n• Средняя: должны быть выполнены некоторые условия, но эксплуатация уязвимости не представляет сложности после их выполнения.\n• Низкая: особые условия не требуются.",
    "AuthenticationHelp" => 'Сколько раз злоумышленник должен пройти аутентификацию на цели, чтобы ее эксплуатировать.
• Многократная: аутентификация требуется два или более раз, даже с одними и теми же учетными данными.
• Однократная: аутентификация требуется один раз.
• Отсутствует: аутентификация не требуется.',
    "ConfidentialityImpactHelp" => 'Влияние на конфиденциальность данных, обрабатываемых системой, в случае эксплуатации.
• Отсутствует: влияния нет.
• Частичное: раскрывается часть информации, но злоумышленник не контролирует, какая именно, либо потери ограничены.
• Полное: раскрывается вся информация в системе.',
    "IntegrityImpactHelp" => 'Влияние на целостность системы в случае эксплуатации.
• Отсутствует: влияния нет.
• Частичное: некоторые данные могут быть изменены, но злоумышленник не контролирует, какие именно, либо масштаб ограничен.
• Полное: полная компрометация целостности системы; злоумышленник может изменять любые файлы.',
    "AvailabilityImpactHelp" => 'Влияние на доступность системы в случае эксплуатации.
• Отсутствует: влияния нет.
• Частичное: снижение производительности или перебои в доступности.
• Полное: полное отключение затронутого ресурса.',
    "RemediationLevelHelp" => 'Уровень доступного устранения уязвимости.
• Официальное исправление: доступно полное решение от поставщика.
• Временное исправление: доступно официальное, но временное исправление.
• Обходное решение: существует неофициальное решение не от поставщика.
• Недоступно: решения нет или его невозможно применить.',
    "ReportConfidenceHelp" => 'Степень уверенности в существовании уязвимости и достоверности ее технических деталей.
• Не подтверждено: единственный неподтвержденный отчет из источника; сама проблема носит предположительный характер.
• Не подкреплено: несколько независимых источников сообщают об одном и том же поведении, но первопричина не подтверждена.
• Подтверждено: поставщик признал проблему, либо она подтверждена анализом исходного кода или эксплойта.',
    "CollateralDamagePotentialHelp" => 'Возможность гибели людей, потери физических активов или финансовых потерь в случае эксплуатации уязвимости.
• Отсутствует: такие потери маловероятны.
• От низкой до средней: возможны умеренные потери.
• Высокая: катастрофическое влияние на активы, доходы или безопасность организации.',
    "TargetDistributionHelp" => 'Доля уязвимых систем в вашей среде.
• Отсутствует: целевых систем нет.
• Низкая: уязвимы 1–25% систем.
• Средняя: уязвимы 26–75% систем.
• Высокая: уязвимы 76–100% систем.',
    "ConfidentialityRequirementHelp" => 'Насколько важна для вашей организации конфиденциальность затронутого актива.
• Низкая: потеря конфиденциальности оказывает ограниченное влияние.
• Средняя: оказывает серьезное влияние.
• Высокая: оказывает катастрофическое влияние.',
    "IntegrityRequirementHelp" => 'Насколько важна для вашей организации целостность затронутого актива.
• Низкая: потеря целостности оказывает ограниченное влияние.
• Средняя: оказывает серьезное влияние.
• Высокая: оказывает катастрофическое влияние.',
    "AvailabilityRequirementHelp" => "Насколько важна для вашей организации доступность затронутого актива.\n• Низкая: потеря доступности имеет ограниченное влияние.\n• Средняя: имеет серьезное влияние.\n• Высокая: имеет катастрофическое влияние.",
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'Как злоумышленнику нужно добраться до этой уязвимости и активировать её: где он должен находиться, насколько сложна атака и требуется ли предварительная аутентификация.',
    'BaseScoreImpactMetricsDescription' => 'Что произойдет, если уязвимость будет успешно использована: как это повлияет на конфиденциальность, целостность и доступность затронутой системы.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'Как меняется реальная угроза этой уязвимости с течением времени: текущее состояние эксплойт-кода, доступные способы устранения и степень достоверности отчетов о ее существовании.',
    'EnvironmentalScoreMetricsDescription' => 'Как риск, связанный с этой уязвимостью, зависит от вашей среды: потенциальный ущерб в реальных условиях и количество фактически затронутых ваших систем.',
    'ImpactSubscoreModifiersDescription' => 'Корректирует влияние базовой оценки в зависимости от того, насколько конфиденциальность, целостность и доступность важны для этого конкретного актива.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'Если эксплуатация угрозы произойдет, какой ущерб будет нанесен?
0 = Ничего
5 = Данные отдельного пользователя скомпрометированы или затронуты.
10 = Полное уничтожение системы или данных',
    'ReproducibilityHelp' => 'Насколько легко воспроизвести эксплуатацию угрозы?
0 = Очень сложно или невозможно, даже для администраторов приложения.
5 = Требуется один или два шага, возможно, нужно быть авторизованным пользователем.
10 = Достаточно веб-браузера и адресной строки, без аутентификации.',
    'ExploitabilityHelp' => 'Что необходимо для эксплуатации этой угрозы?
0 = Продвинутые знания в программировании и сетях, специальные или продвинутые инструменты атаки.
5 = В Интернете существует вредоносное ПО, либо эксплуатация легко выполняется с помощью доступных инструментов атаки.
10 = Достаточно веб-браузера',
    'AffectedUsersHelp' => 'Сколько пользователей будет затронуто?' . "\n" . '0 = Нет' . "\n" . '5 = Некоторые пользователи, но не все' . "\n" . '10 = Все пользователи',
    'DiscoverabilityHelp' => 'Насколько легко обнаружить эту угрозу?
0 = Очень сложно или невозможно; требуется исходный код или административный доступ.
5 = Можно выяснить путем подбора или мониторинга сетевых трассировок.
9 = Подробности о подобных дефектах уже находятся в открытом доступе и легко обнаруживаются с помощью поисковой системы.
10 = Информация видна в адресной строке веб-браузера или в форме.',
