    'AssetScoring' => 'Оценка активов',
    'AssetScoringSettingsHint' => 'Каждому активу присваивается рейтинг «Низкий», «Умеренный» или «Высокий» по конфиденциальности, целостности и доступности; для конфиденциальности вместо этого можно выбрать «Неприменимо», и тогда она исключается из обоих результатов. Категория FIPS актива — это наивысший из трёх рейтингов. Взвешенный балл — это взвешенное среднее трёх значений уровней, а пороги диапазонов преобразуют этот балл в диапазон «Низкий», «Умеренный» или «Высокий». Изменение этих настроек немедленно пересчитывает оценку всех активов.',
    'Weights' => 'Веса',
    'AssetScoringWeightsHint' => 'Насколько каждая цель учитывается во взвешенном балле: от 0 до 100, до двух знаков после запятой. Вес 0 исключает эту цель. Целостность и доступность не могут одновременно иметь вес 0, потому что конфиденциальность со значением «Неприменимо» всегда исключается.',
    'LevelValues' => 'Значения уровней',
    'AssetScoringLevelValuesHint' => 'Число, которое каждая оценка вносит во взвешенный балл: больше 0 и не более 100, не более двух знаков после запятой; значение для «Низкий» должно быть меньше значения для «Умеренный», а оно — меньше значения для «Высокий». Значения по умолчанию: Низкий 1, Умеренный 2 и Высокий 3.',
    'BandThresholds' => 'Пороги диапазонов',
    'AssetScoringBandThresholdsHint' => 'Взвешенный балл, равный порогу или превышающий его, относится к соответствующему диапазону, а балл ниже порога «Умеренный» относится к диапазону «Низкий». Диапазон «Умеренный» должен начинаться выше значения «Низкий», а «Высокий» — выше «Умеренного» и не выше значения «Высокий».',
    'ModerateStartsAt' => 'Умеренный начинается с',
    'HighStartsAt' => 'Высокий начинается с',
    'DefaultScoringForNewAssets' => 'Оценка по умолчанию для новых активов',
    'AssetScoringDefaultsHint' => 'Предварительно выбирает эти рейтинги, когда кто-либо добавляет актив в форме актива. Активы, созданные через обнаружение, импорт или API, остаются без оценки, если не указаны их собственные рейтинги. Оставьте все три значения «Не задано», чтобы отключить это.',
    'AssetScoringWeightsInvalid' => 'Весовые коэффициенты оценки активов должны быть числами от 0 до 100 с не более чем двумя знаками после запятой, при этом показатели целостности и доступности не могут быть одновременно равны 0.',
    'AssetScoringValuesInvalid' => 'Значения уровней оценки активов должны быть числами больше 0 и до 100 не более чем с двумя знаками после запятой, при этом «Низкий» меньше «Умеренного», а «Умеренный» меньше «Высокого».',
