    'AssetScoringResultHelpLabel' => 'Пояснение: {$result}',
    'AssetScoringScoreHelp' => 'Взвешенная оценка объединяет три рейтинга в одно число от {$low} до {$high}. Каждый рейтинг преобразуется в заданное значение, и каждое из них умножается на вес своей цели. Результаты складываются и делятся на сумму весов. Конфиденциальность со значением «Неприменимо» исключается вместе со своим весом. Заданные значения и веса настраиваются в Настройках. Прежде чем будет показана оценка, должны быть оценены все три цели.',
    'AssetScoringCategorizationHelp' => 'Категорирование безопасности по FIPS 199 определяется по максимальному уровню: это наивысший рейтинг среди применимых целей. Один высокий рейтинг делает актив высоким, независимо от остальных. Значение «Неприменимо» игнорируется.',
    'AssetScoringBandHelp' => 'Диапазон присваивает взвешенному баллу оценку по шкале «Низкий», «Умеренный» или «Высокий». Оценка ниже {$moderate} — низкая, от {$moderate} до {$highAt} — умеренная, а {$highAt} и выше — высокая. Пороговые значения настраиваются в разделе «Настройки».',
