    'UserImportPasswordsShownOnce' => 'Эти временные пароли были стерты из SimpleRisk, и их нельзя показать еще раз. Скопируйте их сейчас. Каждый пользователь должен изменить свой пароль при первом входе.',
    'UserImportPasswordsUnavailable' => 'Временные пароли больше нельзя показать. Они показываются один раз, только администратору, который начал импорт, и только во вкладке браузера, в которой он был начат, а SimpleRisk не хранит ничего, что позволило бы показать их еще раз. Задайте новый пароль для каждого нового пользователя, отредактировав пользователя.',
    'UserImportBackgroundNote' => 'Эта страница обновляется автоматически, и импорт продолжается, даже если вы её покинете. Откройте страницу снова, чтобы увидеть результат.',
