    'PleaseEnterAValidEmailAddress' => 'Пожалуйста, введите действительный адрес электронной почты.',
    'RiskImportedClosedWithoutCloseReason' => 'Риск {$risk_id} ("{$subject}") был импортирован со статусом «Закрытый», но без причины закрытия, поэтому информация о его закрытии неполная. Добавьте причину закрытия в файл и выполните импорт еще раз либо завершите закрытие на странице риска.',
    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'Включить HTTP Strict Transport Security (HSTS)',
    'EnableHSTSHelp' => 'Указывает браузерам подключаться к SimpleRisk только по HTTPS в течение указанного ниже максимального срока. Включайте эту функцию только после того, как HTTPS будет надежно работать на этом сайте: браузеры, которые видели заголовок, откажут в использовании обычного HTTP, а неисправный сертификат нельзя будет обойти до истечения максимального срока действия. Начните с короткого максимального срока действия, например, 300 секунд, и увеличьте его после проверки HTTPS.',
    'HSTSMaxAge' => 'Максимальный срок действия HSTS (секунды)',
