    'HSTSIncludeSubdomains' => 'Применять HSTS ко всем поддоменам',
    'HSTSIncludeSubdomainsHelp' => 'Также принудительно включает HTTPS для каждого поддомена этого узла. Оставьте выключенным, если какой-либо поддомен обслуживается по обычному HTTP.',
